def f(inputs):
    def leapYear(year: int) -> bool:
        return year % 400 == 0 or (year % 100!= 0 and year % 4 == 0)

    def countDays(staticDate: List[int], movingDate: List[int]) -> int:
        monthDays = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        days = 0
        for ye in range(staticDate[0], movingDate[0]):
            days += 365 + leapYear(ye)
        for mont in range(staticDate[1], movingDate[1]):
            days += monthDays[mont]
        for da in range(staticDate[2], movingDate[2]):
            days += 1
        return days - 1  # subtract 1 to exclude the end date itself

    result = []
    for y1, m1, d1, y2, m2, d2 in inputs:
        if y1*y2*m1*m2*d1*d2 < 0:
            result.append(0)  # input ended by negative number
        else:
            # data validation
            if not (0 <= y1 <= 10000):
                y1 = 2000
            if m1 <= 0 or m2 <= 0 or m1 > 12 or m2 > 12:
                m1 = m2 = 1
            if d1 <= 0 or d2 <= 0 or d1 > 31 or d2 > 31:
                d1 = d2 = 1
            if y2 < y1 or (y2 == y1 and (m2 < m1 or (m2 == m1 and d2 < d1))):
                y2, m2, d2, y1, m1, d1 = y1, m1, d1, y2, m2, d2

            staticDate = [y1, m1, d1]
            movingDate = [y2, m2, d2]
            # Correct February's day count
            if staticDate[0] == staticDate[1] == movingDate[0] == movingDate[1] == 2:  # only calculate days from Feb to Feb
                if movingDate[2] > staticDate[2] + 29 and not leapYear(staticDate[0]):  # skip Feb 29th if not leap year
                    movingDate[2] -= 1
            else:  # count dates across years or months
                monthDays = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
                for i in range(staticDate[0], movingDate[0]):
                    monthDays[2] = 29 if leapYear(i) else 28
                if leapYear(movingDate[0]):
                    monthDays[2] = 29  # ensure the leap year is considered
            result.append(countDays(staticDate, movingDate))
    return result        
